import {core} from './data/lessons-core.js';import {extra} from './data/lessons-extra.js';import {practice} from './data/lessons-practice.js';import {depth} from './data/lessons-depth.js';import {cases} from './data/cases.js';import {deepDives} from './data/deep-dives.js';import {coverage} from './data/coverage.js';import {sources,checkedOn} from './data/sources.js';import {featuredLessons} from './data/featured-lessons.js';import {diagram} from './data/diagrams.js';import {artwork} from './data/artworks.js';import {motionDiagram} from './data/motion-diagrams.js';import {expanded0610} from './data/expanded-lessons-06-10.js';import {expanded1115} from './data/expanded-lessons-11-15.js';import {expanded1620} from './data/expanded-lessons-16-20.js';import {workedCases} from './data/worked-cases-06-20.js';import {decisionChecks} from './data/decision-checks-06-20.js';
Object.assign(featuredLessons,expanded0610,expanded1115,expanded1620);
for(const [id,chapter] of Object.entries(workedCases)){chapter.paragraphs.push(decisionChecks[id]);featuredLessons[id].chapters.push(chapter)}
const lessons=[core[0],extra[0],...core.slice(1,3),extra[2],...core.slice(3,5),extra[1],...core.slice(5),...practice,...depth],byId=Object.fromEntries(lessons.map(x=>[x.id,x]));const app=document.querySelector('#app'),side=document.querySelector('#side');const E=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));const fold=s=>String(s).toLocaleLowerCase('tr').normalize('NFD').replace(/\p{Diacritic}/gu,'');const saved=(key,fallback)=>{try{return JSON.parse(localStorage.getItem(key))??fallback}catch{return fallback}};let progress=saved('tua-progress',{}),bookmarks=saved('tua-bookmarks',{});const save=(key,value)=>{try{localStorage.setItem(key,JSON.stringify(value))}catch{}};let libraryLevel='Tümü',libraryQuery='';
function link(id,label){return `<a href="#lesson/${E(id)}">${E(label||byId[id]?.title||id)}</a>`}function badge(level){return `<span class="signal ${level==='Uygulama'?'practice':level==='Derinleşme'?'deep':''}">${E(level)}</span>`}function meta(l){return `${badge(l.level)}<span>${E(l.topic)}</span><span>${l.minutes} dk</span><span>Doğrulama: ${E(l.verified)}</span>`}function qstate(id){return progress[id]?'Tamamlandı':'Başlanmadı'}
function sidebar(route){let items=[['home','Ana sayfa'],['path','Başlangıç yolu'],['library','Tüm dersler'],['cases','Uçtan uca vakalar'],['labs','Etkileşimli örnekler'],['capstone','Bitirme çalışması'],['glossary','Sözlük'],['sources','Kaynak merkezi'],['legacy','Eski kaynak eşleştirmesi'],['coverage','Kapsam matrisi']];side.innerHTML=`<p class="side-title">Gezinme</p>${items.map(([id,n])=>`<a href="#${id}" ${route===id?'aria-current="page"':''}>${n}</a>`).join('')}<div class="side-group"><p class="side-title">İlerlemen</p><div class="progress" aria-label="Tamamlanan ders oranı"><span style="width:${Math.round(Object.keys(progress).filter(k=>progress[k]&&byId[k]).length/lessons.length*100)}%"></span></div><p class="small">${Object.keys(progress).filter(k=>progress[k]&&byId[k]).length} / ${lessons.length} ders tamamlandı</p><a href="#bookmarks">Yer imlerim</a></div>`}
function shell(eyebrow,title,body,wide=false){return `<div class="${wide?'wide':'content'}"><p class="eyebrow">${E(eyebrow)}</p><h1>${E(title)}</h1>${body}</div>`}
function row(l,i){return `<li><a href="#lesson/${E(l.id)}"><strong>${i!==undefined?`<span class="number">${String(i+1).padStart(2,'0')}</span>`:''}${E(l.title)}</strong><span class="meta">${E(l.level)} · ${l.minutes} dk · ${E(qstate(l.id))}</span><small>${E(l.topic)} · ${E(l.outcomes[0].split(': ').slice(1).join(': '))}</small></a></li>`}
function home(){let first=lessons.slice(0,5);return `<div class="wide"><section class="hero"><p class="eyebrow">PM ve PO için teknik öğrenme alanı</p><h1>Sistemleri anlayın. Ürün kararlarını daha iyi verin.</h1><p class="lead">Yazılım geliştirme ve AI engineering kavramlarını gerçekçi ürün akışları üzerinden öğrenin. Her ders, neyi açıklamanız, neyi uygulamanız ve hangi kararı verebilmeniz gerektiğini söyler.</p><form class="hero-search" id="homeSearch"><label class="sr-only" for="homeQuery">Derslerde ara</label><input id="homeQuery" type="search" placeholder="Örn. timeout, SQL, RAG, yetkilendirme" autocomplete="off"><button type="submit">Ara</button></form><p class="small">Yeni başlayanlar için sıralı yol; deneyimliler için konu ve seviye bazlı başvuru. PM/PO görev sınırları kuruma göre değişir.</p></section><section><div class="section-heading"><h2>Buradan başlayın</h2><a href="#path">Tüm yolu gör</a></div><ol class="row-list">${first.map(row).join('')}</ol></section><div class="columns"><section><div class="section-heading"><h2>Çalışma biçimi</h2></div><p>Önce akışı çizin, sonra kavramı okuyun. Mini soruyu yanıtlayın; açıklamayı kontrol edin. Bir vakada aynı kararın sonucunu görün. Uygulama derslerinde sentetik veri kullanın.</p><a class="button secondary" href="#labs">Uygulamaları aç</a></section><section><div class="section-heading"><h2>Karar için başvuru</h2></div><p>Dersleri seviye ve konuyla filtreleyin. Türkçe ve İngilizce terimlerde arama yapın. Kaynakların hangi iddiayı desteklediğini ve son doğrulama tarihini görün.</p><a class="button secondary" href="#library">Ders dizinini aç</a></section></div><section><div class="section-heading"><h2>Dört tekrar eden vaka</h2><a href="#cases">Tüm vakalar</a></div><div class="case-grid">${cases.map(c=>`<a class="case-tile" href="#case/${c.id}"><h3>${E(c.title)}</h3><p>${E(c.scenario)}</p></a>`).join('')}</div></section></div>`}
function path(){let ordered=lessons.filter(l=>l.level==='Temel');return shell('Ön koşullara dayalı sıra','Başlangıç öğrenme yolu',`<p class="lead">${ordered.length} temel ders. Önerilen sıra, kavramları gerektiği noktadan önce tanıtır. Uygulama ve derinleşme derslerini ilgili temel dersten açabilirsiniz.</p><div class="note"><strong>Tahmini süre nasıl hesaplandı?</strong><p>Her ders için metin okuma, örnek inceleme ve kısa uygulama süresi birlikte tahmin edildi. Hızınız ve konuya yakınlığınız süreyi değiştirebilir.</p></div><ol class="row-list">${ordered.map(row).join('')}</ol><div class="section-heading"><h2>Sonraki adım</h2></div><p>Temel yolu tamamladıktan sonra <a href="#library">Uygulama</a> derslerini ve <a href="#capstone">bitirme çalışmasını</a> seçin. Derinleşme konuları ilgili ürün sorunuyla karşılaştığınızda açılır.</p>`,true)}
function library(){let found=lessons.filter(l=>(libraryLevel==='Tümü'||l.level===libraryLevel)&&fold([l.title,l.topic,l.problem,l.mechanism,l.product,l.tradeoff,l.questions.join(' '),l.terms.join(' '),JSON.stringify(featuredLessons[l.id]||'')].join(' ')).includes(fold(libraryQuery)));return shell('Seviye ve konu bazlı başvuru','Dersler',`<p class="lead">Gerçek ders metninde ve Türkçe/İngilizce terimlerde arayın.</p><label for="librarySearch">Derslerde ara</label><input class="search-input" id="librarySearch" type="search" value="${E(libraryQuery)}" placeholder="Kavram, ürün kararı veya terim"><div class="filters" role="group" aria-label="Seviye filtresi">${['Tümü','Temel','Uygulama','Derinleşme'].map(x=>`<button data-level="${x}" aria-pressed="${x===libraryLevel}">${x}</button>`).join('')}</div><p class="small" id="resultCount">${found.length} ders gösteriliyor</p>${found.length?`<ul class="row-list" id="libraryRows">${found.map(row).join('')}</ul>`:`<div class="empty">Bu aramada ders bulunamadı. Daha kısa veya İngilizce terimi deneyin.</div>`}`,true)}
function memoryCard(m){return m?`<section class="memory-card" aria-label="Hatırlama ve kendini yoklama"><span>AKILDA KALSIN</span><p>${E(m.hook)}</p><details><summary>${E(m.question)}</summary><p>${E(m.answer)}</p></details></section>`:''}
function featuredLessonPage(l,f){
 const src=id=>sources[id]?`<a href="${E(sources[id].url)}" target="_blank" rel="noopener noreferrer">${E(sources[id].title)} ↗</a>`:'';
 const refIds=[...new Set([...f.sources,...l.refs])];
 const related=[...new Set([...l.related,...lessons.filter(x=>x.pre.includes(l.id)).map(x=>x.id)])].filter(id=>byId[id]&&id!==l.id);
 const chapters=f.chapters.map((c,i)=>`<section class="feature-chapter" id="chapter-${l.id}-${i+1}"><div class="chapter-heading"><span>${E(c.label)}</span><h2>${E(c.title)}</h2></div>${c.paragraphs.map(p=>`<p>${E(p)}</p>`).join('')}${c.bullets?`<ul class="chapter-points">${c.bullets.map(x=>`<li>${E(x)}</li>`).join('')}</ul>`:''}${c.sample?`<div class="example-block"><span>ÇALIŞILMIŞ ÖRNEK</span><pre><code>${E(c.sample)}</code></pre></div>`:''}${c.decision?`<div class="decision-callout"><span>ÜRÜN KARARI</span><p>${E(c.decision)}</p></div>`:''}${c.source?`<p class="chapter-source">Kaynak dayanağı: ${src(c.source)}</p>`:''}</section>`).join('');
 return `<article class="feature-lesson"><div class="feature-hero"><div class="crumb"><a href="#path">Başlangıç yolu</a> / Ders ${E(f.number)}</div><p class="eyebrow">DERS ${E(f.number)} / ${E(l.topic)}</p><h1>${E(l.title)}</h1><p class="feature-deck">${E(f.deck)}</p><div class="lesson-meta">${meta({...l,verified:'2026-10-03'})}</div><div class="detail-actions"><button class="action" id="progressButton" data-progress="${l.id}">${progress[l.id]?'Tamamlandı ✓':'Dersi tamamladım'}</button><button class="action secondary" id="bookmarkButton" data-bookmark="${l.id}">${bookmarks[l.id]?'Yer iminden çıkar':'Yer imine ekle'}</button></div></div>${f.motion?motionDiagram(f.motion):diagram(f.diagram)}<div class="feature-layout"><div class="feature-body"><nav class="chapter-nav" aria-label="Bu dersin bölümleri"><span>BU DERSTE</span>${f.chapters.map((c,i)=>`<a href="#chapter-${l.id}-${i+1}">${E(c.title)}</a>`).join('')}</nav><div class="opening-note"><span>ANA FİKİR</span><p>${E(f.thesis)}</p></div>${memoryCard(f.memory)}${chapters}<section class="feature-chapter feature-apply" id="practice-${l.id}"><div class="chapter-heading"><span>UYGULAMA</span><h2>Şimdi siz deneyin</h2></div><p>${E(f.practice.brief)}</p><div class="practice-criteria"><span>TESLİM ÖLÇÜTLERİ</span><ol>${f.practice.deliverables.map(x=>`<li>${E(x)}</li>`).join('')}</ol></div><details><summary>Açıklamalı örnek cevabı göster</summary>${f.practice.model.map(x=>`<p>${E(x)}</p>`).join('')}</details><h3>Ekibe sorulacak sorular</h3><ul>${l.questions.map(q=>`<li>${E(q)}</li>`).join('')}</ul></section>${quiz(l)}<section class="feature-chapter" id="sources-${l.id}"><div class="chapter-heading"><span>KANIT</span><h2>Kaynaklar ve okuma yolu</h2></div><p>Bu dersin anlatımı özgündür. Şema ve ürün örnekleri öğretim için kurgulanmıştır; kaynaklar belirtilen teknik noktaları destekler.</p><ul class="source-list">${refIds.map((id,i)=>{let s=sources[id];return s?`<li><a href="${E(s.url)}" target="_blank" rel="noopener noreferrer">${E(s.title)} ↗</a><small>${E(s.author)} · ${i===0?'Önce oku':'Derinleş'} · Kontrol: ${E(s.checkedOn||checkedOn)}</small><small>${E(s.supports)}</small></li>`:''}).join('')}</ul></section><section class="feature-next"><span>DEVAM</span><h2>Bir sonraki adım</h2><p>${related.length?related.slice(0,3).map(id=>link(id)).join(' · '):'<a href="#capstone">Bitirme çalışması</a>'}</p></section></div><aside class="feature-rail" aria-label="Ders özeti"><div class="rail-inner"><span class="rail-label">ÖĞRENME HEDEFİ</span><ul>${l.outcomes.map(o=>`<li>${E(o.replace(/^[^:]+: /,''))}</li>`).join('')}</ul>${l.pre.length?`<span class="rail-label">ÖN KOŞUL</span><p>${l.pre.map(id=>link(id)).join(' · ')}</p>`:''}<span class="rail-label">ÜRÜN KARARI</span><p>${E(l.decision)}</p><a class="rail-practice" href="#practice-${l.id}">Uygulamaya geç ↓</a></div></aside></div></article>`
}
function lessonPage(l){if(featuredLessons[l.id])return featuredLessonPage(l,featuredLessons[l.id]);let prev=l.pre.length?`<section class="note"><strong>Ön koşullar</strong><p>${l.pre.map(id=>link(id)).join(' · ')}</p></section>`:'';let related=[...new Set([...l.related,...lessons.filter(x=>x.pre.includes(l.id)).map(x=>x.id)])].filter(id=>byId[id]&&id!==l.id);let refs=l.refs.map((id,i)=>{let s=sources[id];return s?`<li><a href="${E(s.url)}" target="_blank" rel="noopener noreferrer">${E(s.title)}</a><small>${E(s.author)} · ${i===0?'Önce oku':'Derinleş'} · Erişim kontrolü: ${E(checkedOn)} · ${E(s.status)}</small><small>Desteklediği nokta: ${E(s.supports)}</small></li>`:''}).join('');return `<article class="content"><div class="crumb"><a href="#library">Dersler</a> / ${E(l.topic)}</div><p class="eyebrow">${E(l.topic)}</p><h1>${E(l.title)}</h1><div class="lesson-meta">${meta(l)}</div><p class="small">Süre dayanağı: ${E(l.durationBasis)}</p><div class="detail-actions"><button class="action" id="progressButton" data-progress="${l.id}">${progress[l.id]?'Tamamlandı ✓':'Dersi tamamladım'}</button><button class="action secondary" id="bookmarkButton" data-bookmark="${l.id}">${bookmarks[l.id]?'Yer iminden çıkar':'Yer imine ekle'}</button></div>${prev}<section class="article-section"><h2>Bu dersin çıktıları</h2><ul>${l.outcomes.map(o=>`<li>${E(o)}</li>`).join('')}</ul></section><section class="article-section"><h2>Hangi sorunu çözüyor?</h2><p>${E(l.problem)}</p></section><section class="article-section"><h2>Nasıl çalışıyor?</h2><p>${E(l.mechanism)}</p>${l.example?`<pre><code>${E(l.example)}</code></pre>`:''}</section><section class="article-section"><h2>Ürün akışında nasıl görünür?</h2><p>${E(l.product)}</p>${l.caseId?`<p>İlgili vaka: <a href="#case/${l.caseId}">${E(cases.find(c=>c.id===l.caseId)?.title)}</a></p>`:''}</section><section class="article-section"><h2>İlgili ürün kararı</h2><p>${E(l.decision)}</p></section><section class="article-section"><h2>Seçenekler ve ödünleşimler</h2><p>${E(l.tradeoff)}</p>${l.misconception?`<div class="note gold"><strong>Yaygın yanlış anlama</strong><p>${E(l.misconception)}</p></div>`:''}</section>${(deepDives[l.id]||[]).map(d=>`<section class="article-section"><h2>${E(d.title)}</h2><p>${E(d.text)}</p></section>`).join('')}<section class="article-section"><h2>Ekibe sorulacak sorular</h2><ul>${l.questions.map(q=>`<li>${E(q)}</li>`).join('')}</ul></section><section class="exercise"><h2>Kısa uygulama</h2><p>${E(l.exercise)}</p><details><summary>Açıklamalı örnek cevabı göster</summary><p>${E(l.answer)}</p></details></section>${quiz(l)}<section class="article-section"><h2>Kaynaklar</h2><ul class="source-list">${refs}</ul><p class="small">Ders metni özgün öğretim anlatımıdır. Sentetik ürün örnekleri ve karar çıkarımları kaynakların bire bir iddiası değildir.</p></section><section class="article-section"><h2>Sonraki uygun dersler</h2><p>${related.length?related.map(id=>link(id)).join(' · '):'Bu dersden sonra bitirme çalışmasında bilgiyi uygulayın.'}</p></section></article>`}
function quiz(l){let q=l.quiz;return `<section class="quiz" data-quiz="${l.id}"><h2>Mini değerlendirme</h2><p>${E(q.q)}</p><fieldset><legend class="small">Bir yanıt seçin</legend>${q.options.map((x,i)=>`<label><input type="radio" name="quiz-${l.id}" value="${i}"> ${E(x)}</label>`).join('')}</fieldset><button class="action" data-check="${l.id}">Yanıtı kontrol et</button><p class="quiz-feedback" role="status"></p></section>`}
function casePage(c){let sections=[['Kullanıcı akışı',c.userFlow],['Sistem akışı',c.systemFlow]];return shell('Eğitim için kurgulanmış vaka',c.title,`<p class="lead">${E(c.scenario)}</p><div class="columns">${sections.map(([h,steps])=>`<section><div class="section-heading"><h2>${h}</h2></div><ol>${steps.map(s=>`<li>${E(s)}</li>`).join('')}</ol></section>`).join('')}</div>${[['Veri hareketi',c.data],['Bağımlılıklar',c.dependencies],['Başarısızlık senaryoları',c.failures],['Ölçüm',c.measurement],['Ürün kararları',c.decisions]].map(([h,t])=>`<section class="article-section"><h2>${h}</h2><p>${E(t)}</p></section>`).join('')}<section class="article-section"><h2>Bu vakayı işleyen dersler</h2><ul class="row-list">${c.lessons.map(id=>row(byId[id])).join('')}</ul></section>`,true)}
function casesPage(){return shell('Tekrar eden ürün bağlamları','Uçtan uca vakalar',`<p class="lead">Her vaka eğitim için kurgulandı. Aynı akışın kullanıcı davranışı, sistem yolu, veri, hata, ölçüm ve karar yüzleri birlikte okunur.</p><div class="case-grid">${cases.map(c=>`<a class="case-tile" href="#case/${c.id}"><h3>${E(c.title)}</h3><p>${E(c.scenario)}</p></a>`).join('')}</div>`,true)}
function glossary(){const map={ 'İstemci — client':'Kullanıcı veya başka sistem adına isteği başlatan yazılım.','Sunucu — server':'İsteği işleyen ve yanıtlayan hizmet.','Önyüz — frontend':'Kullanıcının etkileştiği görünüm ve istemci davranışı.','Arkayüz — backend':'İş kuralları, veri erişimi ve servis davranışı.','İstek — request':'İstemcinin sunucuya gönderdiği işlem talebi.','Yanıt — response':'Sunucunun isteğe verdiği durum, başlık ve içerik.','Başlık — header':'İstek veya yanıtın ek meta bilgisi.','Gövde — body':'Taşınan veri içeriği.','Oturum — session':'Birden fazla istek boyunca kullanıcı bağlamını sürdürme yolu.','Uç nokta — endpoint':'API’de belirli yol ve işleme bağlanan erişim noktası.','Şema — schema':'Verinin alan, tip ve kısıt tanımı.','Geriye dönük uyumluluk — backward compatibility':'Eski istemcinin yeni sistemle çalışabilmesi.','Kimlik doğrulama — authentication':'Kullanıcının veya hizmetin kim olduğunu doğrulama.','Yetkilendirme — authorization':'Doğrulanan öznenin işlem ve kaynağa erişim izni.','Varlık — entity':'Ayrı kimliği ve yaşam döngüsü olan veri nesnesi.','Birincil anahtar — primary key':'Bir kaydı benzersiz tanımlayan anahtar.','Yabancı anahtar — foreign key':'Kayıtlar arasında referans sağlayan anahtar.','Boş değer — null':'Alan için tanımlanan yokluk veya bilinmezlik; iş anlamı sözlükte yazılır.','Durum kümesi — enum':'Sınırlı izinli değerler kümesi.','Saat dilimi — time zone':'Yerel takvim zamanı ile mutlak zaman arasındaki bölgesel kurallar.','Kabul kriteri — acceptance criterion':'Davranışın doğru sayılacağı test edilebilir koşul.','Mutlu yol — happy path':'Ana başarı akışı.','Uç durum — edge case':'Normal akıştan sapan ama tanımlanması gereken durum.','Zaman aşımı — timeout':'Belirlenen sürede yanıt gelmemesi.','Yeniden deneme — retry':'İsteğin belirli koşullarda tekrarı.','Üstel bekleme — exponential backoff':'Tekrarlar arasında giderek artan bekleme.','Kuyruk — queue':'İşin daha sonra tüketilmek üzere tutulduğu yapı.','Olay — event':'Gerçekleşmiş durumu bildiren kayıt/mesaj.','Nihai tutarlılık — eventual consistency':'Kopyaların belirli süre farklı kalıp koşullar sağlandığında yakınsaması.','Önbellek — cache':'Hız için tutulan veri kopyası.','Yaşam süresi — TTL':'Kopyanın yeniden doğrulanmadan kullanılabileceği süre.','Geçersizleştirme — invalidation':'Eski kopyanın artık kullanılmamasını sağlama.','Hizmet seviyesi göstergesi — SLI':'Kullanıcıyla ilgili hizmet davranışının ölçümü.','Hedef — SLO':'SLI için hedeflenen aralık.','İz — trace':'Tek isteğin dağıtık adımlarını bağlayan kayıt.','Çıkarım — inference':'Eğitilmiş modelle yeni girdiye çıktı üretme.','Bağlam penceresi — context window':'Modelin çağrıda işleyebildiği sınırlı bağlam.','Gömme — embedding':'Metin/öğe anlamını sayısal vektörle temsil etme.'};let terms=[...new Set(lessons.flatMap(l=>l.terms))].sort((a,b)=>a.localeCompare(b,'tr'));return shell('Türkçe / İngilizce','Sözlük',`<p>Terimler ilgili derslerde ilk kullanımda açıklanır. Sözlük hızlı geri dönüş içindir.</p><dl class="glossary-list">${terms.map(t=>`<dt>${E(t)}</dt><dd>${E(map[t]||'İlgili derste kullanım bağlamıyla açıklanır.')} ${lessons.find(l=>l.terms.includes(t))?link(lessons.find(l=>l.terms.includes(t)).id,'Dersi aç'):''}</dd>`).join('')}</dl>`,true)}
function sourcePage(){let used=new Set([...lessons.flatMap(l=>l.refs),...Object.values(featuredLessons).flatMap(f=>f.sources)]);return shell('Kaynak ve doğrulama','Kaynak merkezi',`<p class="lead">Öğretim metni bu sitede okunabilir. Bağlantılar birincil kaynaklara derinleşme olanağı verir. Erişim durumu ve iddia desteği ayrı kaydedildi.</p><p>İlk 20 derse eklenen kaynaklar 3 Ekim 2026, önceki kaynaklar ${E(checkedOn)} tarihinde kontrol edildi. “Otomatik içerik kontrolü bekliyor” bağlantının kırık olduğu anlamına gelmez. Sürüme bağlı davranışlar tekrar doğrulanmalıdır.</p><ul class="source-list">${Object.entries(sources).filter(([id])=>used.has(id)).map(([id,s])=>`<li><a href="${E(s.url)}" target="_blank" rel="noopener noreferrer">${E(s.title)}</a><small>${E(s.author)} · Tam URL: ${E(s.url)}</small><small>Destek: ${E(s.supports)}</small><small>Kontrol: ${E(s.checkedOn||checkedOn)} · ${E(s.status)}</small></li>`).join('')}</ul><p><a href="#legacy">Notion eşleştirmesi ve erişim notu</a> · <a href="#coverage">Kapsam matrisi</a></p>`,true)}
function bookmarksPage(){let list=lessons.filter(l=>bookmarks[l.id]);return shell('Bu cihazdaki kayıt','Yer imlerim',list.length?`<ul class="row-list">${list.map(row).join('')}</ul>`:'<div class="empty">Henüz yer imi eklenmedi. Ders sayfasındaki düğmeyi kullanın.</div>')}
function capstone(){let l=byId.bitirme;return shell('Bütünleştirici görev','Bitirme çalışması',`<p class="lead">Bir dijital paket satın alma özelliğini, teknik ekiple gözden geçirilebilir düzeyde tasarlayın. Gerçek veri veya ödeme hesabı kullanmayın.</p><div class="note"><strong>Teslim paketi</strong><ol><li>Problem ve kapsam</li><li>Kullanıcı ve sistem akışı</li><li>Veri modeli ve sahiplik</li><li>Durum/hata davranışları</li><li>Ölçüm planı</li><li>Test, rollout ve rollback</li></ol></div><div class="section-heading"><h2>Değerlendirme rubriği</h2></div><table class="step-table"><thead><tr><th>Ölçüt</th><th>Puan</th><th>Güçlü çözüm</th></tr></thead><tbody>${[['Problem ve varsayımlar','15','Çözüm varsayımı ile kullanıcı problemi ayrılmış.'],['Akış ve bağımlılıklar','15','İstemci, sunucu, sağlayıcı ve eski istemci sınırları görünür.'],['Veri ve tekillik','20','Sipariş, girişim ve hak kimlikleri; tekillik kuralı açık.'],['Hata ve toparlanma','20','Timeout, kayıp yanıt, tekrar, webhook yinelenmesi ve uzlaşma var.'],['Ölçüm ve test','15','SLI, guardrail, sentetik test ve veri doğrulama tanımlı.'],['Yayın ve geri dönüş','15','Kademeli açma, alarm, geri alma ve veri etkisi ayrılmış.']].map(r=>`<tr><td>${r[0]}</td><td>${r[1]}</td><td>${r[2]}</td></tr>`).join('')}</tbody></table><details class="answer"><summary>Açıklamalı örnek çözümü aç</summary><p>${E(l.answer)}</p><p>Alternatif: sağlayıcı durumu anında sorgulanamıyorsa işlem <em>unknown</em> olarak tutulur, kullanıcıya takip referansı verilir ve operasyonel uzlaşma daha sonra tamamlanır. Kapsam ve SLA’ya göre iki çözüm de doğru olabilir.</p></details><p>${link('bitirme','Ders yönergesi ve mini değerlendirme')}</p>`,true)}
function legacy(){let groups=[['HTTP durum kodları, IP, DNS, subdomain','Geliştir','http, urun-akisi','Kısa tanımlar ürün akışına ve hata davranışına bağlandı.'],['SOAP/GraphQL/REST, WebSocket, webhook, gRPC, API tasarımı','Birleştir','api-sozlesmesi, dagitik','Teknoloji listesi sözleşme ve kullanım kararı etrafında toplandı.'],['Cache, Redis, Hazelcast, API performance','Güncelle','cache, operasyon','Teknoloji isimleri yerine tazelik, gecikme ve kullanıcı etkisi işlendi.'],['Microservice, gateway, proxy, OSI, 12-factor','Birleştir','dagitik, mimari-secim, altyapi','Ayrıntılar ihtiyaç temelli derinleşmeye taşındı.'],['Git, queue, pub-sub, Kafka','Geliştir','test-yayin, dagitik','Ürün teslimi ve asenkron hata davranışıyla bağlandı.'],['JWT','Güncelle','kimlik-yetki','Token biçimi ile kimlik/yetki ayrı anlatıldı.'],['Visa ve TinyURL örnekleri','Gerekçesiyle çıkar','odeme-vakasi, bitirme','Doğrulanmamış şirket ayrıntısı ve sistem tasarımı alıştırması yerine sentetik, ürün kararlı ödeme vakası kondu.'],['Slack bildirim örneği','Geliştir','kampanya-vakasi','Tek ürün uygulamasına bağlı anlatım, sentetik bildirim vakasına çevrildi.'],['Useful articles bağlantıları','Güncelle','sources','Dış listeler yerine iddia bazlı birincil kaynak envanteri kondu.']];return shell('Eski kaynak envanteri','Notion eşleştirmesi',`<p class="lead">Eski Notion sayfası tarayıcıda açıldı. İçindekiler başlıkları ve ilk bölümlerin görünen metinleri incelendi; uzun sayfanın tüm blokları ve alt sayfa bulunup doğrulanamadı. Bu tablo, görülebilen başlıklar üzerinden verilen editoryal karardır; okunmamış bölümlere ilişkin içerik iddiası değildir.</p><p><a href="${E(sources.notion.url)}" target="_blank" rel="noopener noreferrer">Eski TECHNICAL PM sayfası</a> · Kontrol: ${E(checkedOn)}. Ekli Notion export sunulmadı.</p><table class="step-table"><thead><tr><th>Mevcut başlıklar</th><th>Karar</th><th>Yeni yer</th><th>Gerekçe</th></tr></thead><tbody>${groups.map(([old,decision,newLoc,reason])=>`<tr><td>${E(old)}</td><td>${E(decision)}</td><td>${E(newLoc)}</td><td>${E(reason)}</td></tr>`).join('')}</tbody></table><p>Özgün metnin bütününe erişim olmadan paragraf düzeyinde “koru” kararı verilmedi. İleride export sağlanırsa satır düzeyinde yeniden eşleştirme yapılabilir.</p>`,true)}
function coveragePage(){return shell('A–P kapsam kontrolü','Kapsam matrisi',`<p class="lead">Alanlar PM/PO karar ve uygulama ihtiyaçlarına göre birleştirildi. Bir alanın listede olması uzmanlık eğitimi verildiği anlamına gelmez; sağ sütundaki sınırı okuyun.</p><table class="step-table"><thead><tr><th>Alan</th><th>Dersler</th><th>Sınır</th></tr></thead><tbody>${coverage.map(([name,ids,note])=>`<tr><td>${E(name)}</td><td>${ids.split(', ').map(id=>link(id)).join(' · ')}</td><td>${E(note)}</td></tr>`).join('')}</tbody></table>`,true)}
function labs(){return shell('Sentetik ve sınırları açık','Etkileşimli örnekler',`<p class="lead">Bu örnekler kavramı görünür kılar; gerçek sistem garantisi veya fiyat teklifi vermez.</p><section class="sim" id="httpLab"><h2>1 · HTTP isteğinin parçaları</h2><label for="method">Yöntem</label><select id="method"><option>GET</option><option>POST</option><option>DELETE</option></select><label for="path">Yol</label><select id="path"><option>/campaigns</option><option>/orders/17</option><option>/sessions</option></select><output id="httpOut"></output><p class="small">Varsayım: eğitim API’si; gerçek sunucu çağrısı yapılmaz. Yöntem niyet gösterir, gerçek güvenlik sunucu kuralına bağlıdır.</p></section><section class="sim" id="retryLab"><h2>2 · Timeout ve çift işlem riski</h2><label for="processed">Sunucu isteği işledi mi?</label><select id="processed"><option value="yes">Evet, yanıt kayboldu</option><option value="no">Hayır</option></select><label for="keyReuse">Tekrarda aynı niyet anahtarı mı?</label><select id="keyReuse"><option value="yes">Evet</option><option value="no">Hayır, yeni anahtar</option></select><output id="retryOut"></output><p class="small">Varsayım: sunucu anahtar bazında sonucu atomik saklıyor. Sağlayıcı sınırı ve eşzamanlılık gerçek tasarımda ayrıca ele alınır.</p></section><section class="sim" id="cacheLab"><h2>3 · Cache ve eski veri</h2><label for="ttl">TTL: <span id="ttlValue">30</span> dakika</label><input id="ttl" type="range" min="0" max="120" value="30"><label for="elapsed">Değişiklikten geçen süre: <span id="elapsedValue">10</span> dakika</label><input id="elapsed" type="range" min="0" max="120" value="10"><output id="cacheOut"></output><p class="small">Varsayım: kopya tam değişiklik anında eski değerle dolduruldu; aktif invalidation yok. Gerçekte kopya yaşı değişebilir.</p></section><section class="sim" id="stateLab"><h2>4 · Durum geçişleri</h2><label for="currentState">Mevcut durum</label><select id="currentState"><option value="draft">Taslak</option><option value="processing">İşleniyor</option><option value="completed">Tamamlandı</option><option value="failed">Başarısız</option></select><label for="event">Olay</label><select id="event"><option value="submit">Gönder</option><option value="succeed">Başarılı yanıt</option><option value="fail">Hata</option><option value="retry">Yeniden dene</option></select><output id="stateOut"></output><p class="small">Eğitim durum makinesi; gerçek iş kuralları ve yarış koşulları ayrıca tasarlanır.</p></section><section class="sim" id="aiLab"><h2>5 · AI maliyet ve gecikme</h2><label for="requests">Sorgu sayısı: <span id="requestsValue">10000</span></label><input id="requests" type="range" min="1000" max="100000" step="1000" value="10000"><label for="inputTokens">Giriş tokenı/sorgu: <span id="inputTokensValue">1000</span></label><input id="inputTokens" type="range" min="100" max="10000" step="100" value="1000"><label for="outputTokens">Çıkış tokenı/sorgu: <span id="outputTokensValue">300</span></label><input id="outputTokens" type="range" min="100" max="3000" step="100" value="300"><label for="retries">Tekrar oranı: <span id="retriesValue">5</span>%</label><input id="retries" type="range" min="0" max="50" value="5"><output id="aiOut"></output><p class="small">Eğitim varsayımı: giriş $1 / 1M, çıkış $4 / 1M token; temel model gecikmesi 1,2 sn + 1000 çıkış tokenı başına 0,8 sn. Retrieval, araç, cache, ağ, paralellik, para birimi ve gerçek sağlayıcı fiyatı hariçtir. Tahmin/pazar fiyatı değildir.</p></section>`,true)}
function bindLabs(){let $=id=>document.getElementById(id);function update(){if(!$('method'))return;let m=$('method').value,p=$('path').value;$('httpOut').textContent=`${m} ${p} HTTP/1.1 · Başlık: Accept: application/json · ${m==='GET'?'Gövde genelde kullanılmaz':'Gövde ve yetki koşulu ayrıca tanımlanır'}`;let processed=$('processed').value==='yes',same=$('keyReuse').value==='yes';$('retryOut').textContent=processed?(same?'Aynı niyet: kayıt doğru uygulanmışsa yeni etki oluşmaz; mevcut sonuç sorgulanır.':'Çift işlem riski: yeni anahtar yeni niyet gibi işlenebilir.'):'İlk işlem olmadıysa kontrollü tekrar gerekebilir; önce güvenilir durum kanıtı aranır.';let ttl=+$('ttl').value,elapsed=+$('elapsed').value;$('ttlValue').textContent=ttl;$('elapsedValue').textContent=elapsed;$('cacheOut').textContent=elapsed<ttl?`Eski veri ${ttl-elapsed} dakika daha görünebilir.`:'TTL dolmuş; sonraki okuma yeniden doğrulama gerektirebilir.';let transitions={draft:{submit:'processing'},processing:{succeed:'completed',fail:'failed'},failed:{retry:'processing'},completed:{}};let s=$('currentState').value,e=$('event').value,names={draft:'taslak',processing:'işleniyor',completed:'tamamlandı',failed:'başarısız',submit:'gönder',succeed:'başarılı yanıt',fail:'hata',retry:'yeniden dene'};$('stateOut').textContent=transitions[s][e]?`İzinli geçiş: ${names[s]} → ${names[transitions[s][e]]}`:`Bu modelde ${names[s]} + ${names[e]} geçişi izinli değil.`;let n=+$('requests').value,inp=+$('inputTokens').value,out=+$('outputTokens').value,r=+$('retries').value;for(let id of ['requests','inputTokens','outputTokens','retries'])$(id+'Value').textContent=$(id).value;let cost=n*(inp/1e6*1+out/1e6*4)*(1+r/100),lat=1.2+out/1000*.8;$('aiOut').textContent=`Yaklaşık model maliyeti: $${cost.toFixed(2)} · Tek çağrı varsayımsal gecikmesi: ${lat.toFixed(2)} sn · Tekrarlarla toplam çağrı: ${Math.round(n*(1+r/100))}.`;}document.querySelectorAll('.sim input,.sim select').forEach(el=>el.addEventListener('input',update));update()}
function mountArtwork(route,id){const key=route==='lesson'?id:route==='case'?`case-${id}`:route;const visual=artwork(key);if(!visual)return;let target;if(route==='home'){target=app.querySelector('.hero .lead');target?.closest('.hero')?.classList.add('hero-with-art')}else if(route==='lesson'&&featuredLessons[id]){target=app.querySelector('.feature-hero .feature-deck');target?.closest('.feature-hero')?.classList.add('feature-hero-with-art')}else{target=app.querySelector('.lead')||app.querySelector('h1')}target?.insertAdjacentHTML('afterend',visual)}
let cleanupMotion=()=>{};
function bindMotion(){const fig=app.querySelector('[data-motion]');if(!fig)return;const steps=[...fig.querySelectorAll('[data-motion-step]')],pause=fig.querySelector('[data-motion-pause]'),replay=fig.querySelector('[data-motion-replay]'),reduce=matchMedia('(prefers-reduced-motion: reduce)').matches;let current=0,timer=null,paused=false,seen=false;if(reduce)replay.textContent='İlk adıma dön';const stop=()=>{if(timer)clearInterval(timer);timer=null};const paint=i=>{current=i;fig.style.setProperty('--phase',i);steps.forEach((b,n)=>b.setAttribute('aria-current',n===i?'step':'false'))};const play=()=>{stop();if(reduce||current>=steps.length-1)return;timer=setInterval(()=>{if(current>=steps.length-1){stop();return}paint(current+1);if(current>=steps.length-1){stop();pause.textContent='Bitti';pause.disabled=true;pause.setAttribute('aria-label','Animasyon tamamlandı')}},1700)};const observer=new IntersectionObserver(entries=>{const visible=entries[0]?.isIntersecting;if(visible){if(!seen){seen=true;play()}else if(!paused)play()}else stop()},{threshold:.35});observer.observe(fig);pause.addEventListener('click',()=>{paused=!paused;pause.textContent=paused?'Sürdür':'Durdur';pause.setAttribute('aria-label',paused?'Animasyonu sürdür':'Animasyonu durdur');pause.setAttribute('aria-pressed',String(paused));if(paused)stop();else play()});replay.addEventListener('click',()=>{paused=false;pause.disabled=false;pause.textContent='Durdur';pause.setAttribute('aria-label','Animasyonu durdur');pause.setAttribute('aria-pressed','false');stop();paint(0);play()});steps.forEach((b,i)=>b.addEventListener('click',()=>{stop();paused=true;paint(i);pause.disabled=i===steps.length-1;pause.textContent=pause.disabled?'Bitti':'Sürdür';pause.setAttribute('aria-label',pause.disabled?'Animasyon tamamlandı':'Animasyonu sürdür');pause.setAttribute('aria-pressed','true')}));cleanupMotion=()=>{stop();observer.disconnect()}}
function render(){cleanupMotion();let hash=decodeURIComponent(location.hash.slice(1)||'home'),[route,id]=hash.split('/');sidebar(route);document.querySelectorAll('.primary-nav a').forEach(a=>a.setAttribute('aria-current',a.getAttribute('href')===`#${route}`?'page':'false'));let html=route==='home'?home():route==='path'?path():route==='library'?library():route==='lesson'&&byId[id]?lessonPage(byId[id]):route==='cases'?casesPage():route==='case'&&cases.some(c=>c.id===id)?casePage(cases.find(c=>c.id===id)):route==='labs'?labs():route==='glossary'?glossary():route==='sources'?sourcePage():route==='bookmarks'?bookmarksPage():route==='capstone'?capstone():route==='legacy'?legacy():route==='coverage'?coveragePage():shell('Sayfa bulunamadı','Bu bağlantı geçerli değil','<p><a href="#home">Ana sayfaya dön</a></p>');app.innerHTML=html;mountArtwork(route,id);bindMotion();app.querySelectorAll('.step-table').forEach(t=>{let w=document.createElement('div');w.className='table-wrap';t.parentNode.insertBefore(w,t);w.appendChild(t)});if(route==='labs')bindLabs();if(route==='library'){document.getElementById('librarySearch').addEventListener('input',e=>{libraryQuery=e.target.value;let found=lessons.filter(l=>(libraryLevel==='Tümü'||l.level===libraryLevel)&&fold([l.title,l.topic,l.problem,l.mechanism,l.product,l.tradeoff,l.questions.join(' '),l.terms.join(' '),JSON.stringify(featuredLessons[l.id]||'')].join(' ')).includes(fold(libraryQuery)));document.getElementById('resultCount').textContent=`${found.length} ders gösteriliyor`;let list=document.getElementById('libraryRows');list.outerHTML=found.length?`<ul class="row-list" id="libraryRows">${found.map(row).join('')}</ul>`:'<div class="empty" id="libraryRows">Bu aramada ders bulunamadı.</div>';});document.querySelectorAll('[data-level]').forEach(b=>b.addEventListener('click',()=>{libraryLevel=b.dataset.level;render();document.getElementById('librarySearch').focus()}))}document.title=`${route==='lesson'&&byId[id]?byId[id].title:route==='case'?cases.find(c=>c.id===id)?.title||'Vaka':route==='home'?'Ana sayfa':app.querySelector('h1')?.textContent||'Atlas'} · Teknik Ürün Atlası`;document.querySelector('#main').focus({preventScroll:true});window.scrollTo(0,0)}
document.addEventListener('click',e=>{const a=e.target.closest('a[href^="#chapter-"],a[href^="#practice-"]');if(!a)return;e.preventDefault();document.getElementById(a.getAttribute('href').slice(1))?.scrollIntoView({behavior:window.matchMedia('(prefers-reduced-motion: reduce)').matches?'instant':'smooth'});});document.addEventListener('submit',e=>{if(e.target.id==='homeSearch'){e.preventDefault();libraryQuery=document.getElementById('homeQuery').value;location.hash='#library';if(location.hash==='#library')render()}});document.addEventListener('click',e=>{let b=e.target.closest('button');if(!b)return;if(b.id==='menuButton'){let nav=document.getElementById('primaryNav'),open=!nav.classList.contains('open');nav.classList.toggle('open',open);b.setAttribute('aria-expanded',String(open))}if(b.dataset.progress){let id=b.dataset.progress;progress[id]=!progress[id];save('tua-progress',progress);render()}if(b.dataset.bookmark){let id=b.dataset.bookmark;bookmarks[id]=!bookmarks[id];save('tua-bookmarks',bookmarks);render()}if(b.dataset.check){let id=b.dataset.check,section=b.closest('.quiz'),sel=section.querySelector('input:checked'),out=section.querySelector('.quiz-feedback');if(!sel){out.textContent='Önce bir seçenek seçin.';return}let q=byId[id].quiz,correct=Number(sel.value)===q.correct;out.textContent=`${correct?'Doğru.':'Tekrar düşünün.'} ${q.explain} Doğru yanıt: ${q.options[q.correct]}`}});window.addEventListener('hashchange',()=>{document.getElementById('primaryNav').classList.remove('open');document.getElementById('menuButton').setAttribute('aria-expanded','false');render()});render();
